}

.product-name {
    font-size: 1rem;
    margin: 0;
    font-weight: 600;
}

.product-price {
    font-size: 1.1rem;
    font-weight: 700;
    color: #2a7d2a;
    margin: 0;
}

.product-rating {
    color: #f5a623;
    font-size: 1.1rem;
}

.out-of-stock-badge {
